import { orderPatterns } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message + ": got " + JSON.stringify(actual));
}

function throwsInvalid(patterns: string[]): void {
  try {
    orderPatterns(patterns);
  } catch (error) {
    assert(error instanceof Error && error.message === "invalid pattern", "wrong validation error");
    return;
  }
  throw new Error("expected invalid pattern");
}

const empty: string[] = [];
const emptyResult = orderPatterns(empty);
equal(emptyResult, [], "empty input");
assert(emptyResult !== empty, "empty result is a new array");

const patterns = [
  "/:id",          // 0 static, 1 total
  "/users/:id",    // 1 static, 2 total
  "/health",       // 1 static, 1 total
  "/a/b",          // 2 static, 2 total
  "/users/:name",  // tie with users/id
  "/",             // 0 static, 0 total
  "/a/b",          // duplicate
  "/x_y-9",        // 1 static, 1 total
];
const original = patterns.slice();
equal(orderPatterns(patterns), [
  "/a/b",
  "/a/b",
  "/users/:id",
  "/users/:name",
  "/health",
  "/x_y-9",
  "/:id",
  "/",
], "ranking and stable ties");
equal(patterns, original, "input array is not mutated");
const output1 = orderPatterns(patterns);
const output2 = orderPatterns(patterns);
assert(output1 !== output2 && output1 !== patterns, "output arrays are fresh");
output1.reverse();
equal(orderPatterns(patterns), ["/a/b", "/a/b", "/users/:id", "/users/:name", "/health", "/x_y-9", "/:id", "/"], "output not retained");

for (const bad of [
  "",
  "users",
  "//",
  "/a/",
  "//a",
  "/a//b",
  "/:",
  "/:a-b",
  "/:a$b",
  "/a.b",
  "/é",
  "/a b",
]) throwsInvalid([bad]);
throwsInvalid(["/valid", "/also-valid/:id", "/bad/"]);

equal(orderPatterns(["/A-Z_09", "/:A_09"]), ["/A-Z_09", "/:A_09"], "valid segment character boundaries");

